import java.util.Scanner;

public class Main {
    static final long INF = Long.MAX_VALUE;
    static final double EPS = 1e-10;
    static final long e5 = 100000L;
    static final long e6 = 1000000L;
    static final long e7 = 10000000L;
    static final long e9 = 1000000000L;
    static final long MOD = e9 + 7;

    static long fast_pow(long base, long exp, long mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLong()) {
            long p = sc.nextLong();
            long k = sc.nextLong();

            if (k == 0) {
                System.out.println(fast_pow(p, p - 1, MOD));
                continue;
            }
            if (k == 1) {
                System.out.println(fast_pow(p, p, MOD));
                continue;
            }

            boolean[] seen = new boolean[(int) p];
            long count_cycles = 0;

            for (long i = 1; i < p; ++i) {
                if (seen[(int) i]) continue;
                long j = i;
                long cycle_len = 0;
                while (!seen[(int) j]) {
                    seen[(int) j] = true;
                    j = (j * k) % p;
                    cycle_len++;
                }
                if (fast_pow(k, cycle_len, p) == 1) {
                    count_cycles++;
                }
            }
            System.out.println(fast_pow(p, count_cycles, MOD));
        }
        sc.close();
    }
}
